import { useReducer } from 'react';

type State = { count: number; on: boolean };

type CounterAction = { type: 'INCREMENT' } | { type: 'DECREMENT' };
type ToggleAction = { type: 'TOGGLE' } | { type: 'RESET' };
type Action = CounterAction | ToggleAction;

const counterReducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'INCREMENT':
      return { ...state, count: state.count + 1 };
    case 'DECREMENT':
      return { ...state, count: state.count - 1 };
    default:
      return state;
  }
};

const toggleReducer = (state: State, action: Action): State => {
  switch (action.type) {
    case 'TOGGLE':
      return { ...state, on: !state.on };
    case 'RESET':
      return { ...state, on: false, count: 0 };
    default:
      return state;
  }
};

function composeReducers<S, A>(
  ...reducers: Array<(state: S, action: A) => S>
) {
  return (state: S, action: A): S =>
    reducers.reduce((s, r) => r(s, action), state);
}

export function useCounterToggle(initial = { count: 0, on: false }) {
  const reducer = composeReducers(counterReducer, toggleReducer);
  const [state, dispatch] = useReducer(reducer, initial);

  return {
    on: state.on,
    count: state.count,
    toggle: () => dispatch({ type: 'TOGGLE' }),
    increment: () => dispatch({ type: 'INCREMENT' }),
    decrement: () => dispatch({ type: 'DECREMENT' }),
    reset: () => dispatch({ type: 'RESET' }),
  };
}

type Action = { type: string };

type Enhancer<S, A extends Action> = (reducer: (state: S, action: A) => S) => (state: S, action: A) => S;

function withLogging<S, A extends Action>(reducer: (state: S, action: A) => S): (state: S, action: A) => S {
  return (state, action) => {
    const next = reducer(state, action);
    console.log(`[${String(action.type)}] ->`, next);
    return next;
  };
}

// Apply enhancers right-to-left, like function composition
function enhanceReducer<S, A extends Action>(
  reducer: (state: S, action: A) => S,
  ...enhancers: Enhancer<S, A>[]
) {
  return enhancers.reduce((acc, enh) => enh(acc), reducer);
}

const enhanced = enhanceReducer(combinedReducer, withLogging);

type Action = { type: string };

type Middleware<S, A extends Action> = (
  ctx: { getState: () => S },
  action: A,
  next: (a: A) => S
) => S;

function withMiddleware<S, A extends Action>(
  reducer: (state: S, action: A) => S,
  middlewares: Middleware<S, A>[]
) {
  return (state: S, action: A): S => {
    let index = 0;
    const ctx = { getState: () => state };
    const next = (a: A): S => {
      if (index < middlewares.length) {
        const mw = middlewares[index++];
        return mw(ctx, a, next);
      }
      return reducer(state, a);
    };
    return next(action);
  };
}

// A middleware that blocks actions while state is locked
const lockMiddleware: Middleware<{ count: number; locked: boolean }, Action> = (
  ctx,
  action,
  next
) => {
  if (ctx.getState().locked && action.type !== 'UNLOCK') {
    return ctx.getState();
  }
  return next(action);
};

import { describe, it, expect } from 'vitest';

const counterReducer = (state: { count: number }, action: { type: string }) => {
  switch (action.type) {
    case 'INCREMENT':
      return { ...state, count: state.count + 1 };
    case 'DECREMENT':
      return { ...state, count: state.count - 1 };
    default:
      return state;
  }
};

describe('counterReducer', () => {
  it('increments the count', () => {
    const next = counterReducer({ count: 0 }, { type: 'INCREMENT' });
    expect(next.count).toBe(1);
  });

  it('decrements the count', () => {
    const next = counterReducer({ count: 5 }, { type: 'DECREMENT' });
    expect(next.count).toBe(4);
  });

  it('returns the same reference for unknown actions', () => {
    const state = { count: 0 };
    const next = counterReducer(state, { type: 'UNKNOWN' });
    expect(next).toBe(state);
  });
});
